alter table accounting.account drop constraint if exists account_type_check;
alter table accounting.account add constraint account_type_check check (type in ('Asset','Equity','Liability','Income','Expense'));
alter table inventory.stock_movement drop constraint if exists stock_movement_quantity_delta_check;
alter table inventory.stock_movement drop constraint if exists stock_movement_value_delta_check;
alter table inventory.stock_movement add constraint stock_movement_qty_ck check (quantity_delta <> 0);
alter table inventory.stock_movement add constraint stock_movement_value_ck check ((quantity_delta > 0 and value_delta > 0) or (quantity_delta < 0 and value_delta <= 0));
create schema if not exists sales;
grant usage on schema sales to rbos_app;
create table sales.customer (tenant_id uuid not null references core.tenant(id), id uuid not null, name text not null check (length(btrim(name)) between 1 and 120), phone text null check (phone is null or length(phone) <= 30), notes text null check (notes is null or length(notes) <= 300), is_active boolean not null default true, created_at timestamptz not null default now(), primary key (tenant_id, id));
create index customer_name_ix on sales.customer (tenant_id, lower(name));
create table sales.sale (tenant_id uuid not null references core.tenant(id), id uuid not null, customer_id uuid null, location_id uuid not null, sale_date date not null, sale_type text not null check (sale_type in ('Cash','UPI','Credit')), total numeric(18,2) not null check (total > 0), amount_paid numeric(18,2) not null check (amount_paid >= 0), pay_method text null check (pay_method is null or pay_method in ('Cash','Bank','UPI')), cost_total numeric(18,2) not null check (cost_total >= 0), idempotency_key text not null check (length(idempotency_key) between 8 and 100), request_hash text not null, journal_entry_id uuid not null, created_by uuid not null, created_at timestamptz not null default now(), primary key (tenant_id, id), unique (tenant_id, idempotency_key), check (amount_paid <= total), check (sale_type = 'Credit' or amount_paid = total), check (sale_type <> 'Credit' or customer_id is not null), foreign key (tenant_id, customer_id) references sales.customer(tenant_id, id), foreign key (tenant_id, location_id) references core.stock_location(tenant_id, id), foreign key (tenant_id, journal_entry_id) references accounting.journal_entry(tenant_id, id));
create table sales.sale_line (tenant_id uuid not null, sale_id uuid not null, product_id uuid not null, quantity numeric(18,3) not null check (quantity > 0), unit_price numeric(18,2) not null check (unit_price >= 0), discount numeric(18,2) not null check (discount >= 0), line_total numeric(18,2) not null check (line_total >= 0), unit_cost numeric(18,4) not null check (unit_cost >= 0), primary key (tenant_id, sale_id, product_id), foreign key (tenant_id, sale_id) references sales.sale(tenant_id, id), foreign key (tenant_id, product_id) references catalog.product(tenant_id, id));
do $$ declare t text; begin foreach t in array array['sales.customer','sales.sale','sales.sale_line'] loop execute format('alter table %s enable row level security', t); execute format('alter table %s force row level security', t); execute format('create policy tenant_isolation on %s for all to rbos_app using (tenant_id = core.current_tenant_id() and core.is_active_member(tenant_id)) with check (tenant_id = core.current_tenant_id() and core.is_active_member(tenant_id))', t); end loop; end $$;
grant select, insert on sales.customer, sales.sale, sales.sale_line to rbos_app;
grant update (name, phone, notes, is_active) on sales.customer to rbos_app;
alter table sales.sale add column number bigint generated always as identity;
